cat > src/command.rs <<'EOF'
//! Turns a request line into a validated [`Command`].
//!
//! Parsing performs steps 1 to 3 of the check order in SPEC section 2: request
//! shape, required parameters, parameter values. Everything that needs state
//! (queue lookup and the per-command rules) happens in the service.

use serde_json::Value;

use crate::error::{Error, ErrorCode, Result};
use crate::params::Params;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Command {
    Tick { seconds: u64 },
}

pub const MAX_TICK_SECONDS: u64 = 1_209_600;

fn invalid_request(message: impl Into<String>) -> Error {
    Error::new(ErrorCode::InvalidRequest, message)
}

pub fn parse(line: &[u8]) -> Result<Command> {
    let text = std::str::from_utf8(line).map_err(|_| invalid_request("line is not valid UTF-8"))?;
    let value: Value =
        serde_json::from_str(text).map_err(|e| invalid_request(format!("invalid JSON: {e}")))?;
    let Value::Object(members) = value else {
        return Err(invalid_request("request is not a JSON object"));
    };
    let params = Params::new(&members);
    let name = match members.get("Command") {
        Some(Value::String(name)) => name.as_str(),
        _ => return Err(invalid_request("Command must be a string")),
    };
    match name {
        "Tick" => parse_tick(&params),
        other => Err(invalid_request(format!("unknown command {other:?}"))),
    }
}

fn parse_tick(p: &Params) -> Result<Command> {
    p.require("Seconds")?;
    let seconds = p.integer("Seconds", 0, MAX_TICK_SECONDS)?.expect("required");
    Ok(Command::Tick { seconds })
}
EOF
cat > src/service.rs <<'EOF'
//! The state of the whole process and the execution of commands.

use serde_json::{json, Value};

use crate::command::Command;
use crate::error::Result;

#[derive(Debug, Default)]
pub struct Service {
    /// Virtual clock, in seconds.
    now: u64,
}

impl Service {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one command and returns its result members as a JSON object.
    pub fn execute(&mut self, command: Command) -> Result<Value> {
        match command {
            Command::Tick { seconds } => {
                self.now += seconds;
                Ok(json!({ "Now": self.now }))
            }
        }
    }
}
EOF
cat > src/lib.rs <<'EOF'
//! miniq: a small in-memory message queue driven by JSON lines.
//!
//! [`run`] implements the line protocol; [`Service`] holds all state and can
//! be driven directly with [`Command`]s.

mod command;
mod error;
mod params;
mod service;

use std::io::{self, BufRead, Write};

use serde_json::{json, Value};

pub use command::Command;
pub use error::{Error, ErrorCode};
pub use service::Service;

/// Reads commands line by line from `input` and writes one response line per
/// command to `output`, flushing after each, until end of input.
pub fn run<R: BufRead, W: Write>(mut input: R, mut output: W) -> io::Result<()> {
    let mut service = Service::new();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = handle_line(&mut service, &line);
        output.write_all(response.as_bytes())?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}

/// Executes one request line and renders the response line (without `\n`).
pub fn handle_line(service: &mut Service, line: &[u8]) -> String {
    let outcome = command::parse(line).and_then(|command| service.execute(command));
    let response = match outcome {
        Ok(Value::Object(mut members)) => {
            members.insert("ok".into(), Value::Bool(true));
            Value::Object(members)
        }
        Ok(_) => unreachable!("commands return JSON objects"),
        Err(error) => json!({
            "ok": false,
            "error": { "code": error.code.as_str(), "message": error.message },
        }),
    };
    response.to_string()
}
EOF
