    fn queue_mut(&mut self, name: &str) -> Result<&mut Queue> {
        let now = self.now;
        let queue = self
            .queues
            .get_mut(name)
            .ok_or_else(|| no_such_queue(name))?;
        queue.expire(now);
        Ok(queue)
