    create(&mut s, "q", json!({}));
    create(&mut s, "f.fifo", json!({"Fifo": true}));
    let set = |name: &str, attributes: Value| json!({"Command": "SetQueueAttributes", "QueueName": name, "Attributes": attributes});
    s.err(json!({"Command": "SetQueueAttributes", "QueueName": "q"}), "MissingParameter");
    s.err(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": null}), "MissingParameter");
    s.err(set("q", json!([])), "InvalidParameterValue");
    s.err(set("missing", json!({"Fifo": true})), "QueueDoesNotExist");
    s.err(set("missing", json!({"Bogus": true})), "InvalidParameterValue");
    s.err(set("q", json!({"Fifo": false})), "UnsupportedOperation");
    s.err(set("q", json!({"Fifo": true, "ContentBasedDeduplication": true})), "UnsupportedOperation");
    s.err(set("q", json!({"ContentBasedDeduplication": true})), "InvalidParameterValue");
    s.ok(set("q", json!({"ContentBasedDeduplication": false})));
    s.ok(set("f.fifo", json!({"ContentBasedDeduplication": true})));
    s.err(set("q", json!({"DeadLetterQueue": "q"})), "InvalidParameterValue");
    s.err(set("q", json!({"MaxReceiveCount": 2})), "InvalidParameterValue");
    s.err(set("q", json!({"DeadLetterQueue": "nope", "MaxReceiveCount": 2})), "QueueDoesNotExist");
    s.err(set("q", json!({"DeadLetterQueue": "q", "MaxReceiveCount": 2})), "InvalidParameterValue");
    s.err(set("q", json!({"DeadLetterQueue": "f.fifo", "MaxReceiveCount": 2})), "InvalidParameterValue");
    create(&mut s, "d", json!({}));
    s.ok(set("q", json!({"DeadLetterQueue": "d", "MaxReceiveCount": 2})));
    s.ok(set("q", json!({"VisibilityTimeout": 9})));
    let a = attributes(&mut s, "q");
    assert_eq!(a["DeadLetterQueue"], "d");
    assert_eq!(a["MaxReceiveCount"], 2);
    assert_eq!(a["VisibilityTimeout"], 9);
    // Failed commands changed nothing.
    assert_eq!(attributes(&mut s, "f.fifo")["DeadLetterQueue"], Value::Null);
}

#[test]
fn list_queues_sorts_by_byte_value_and_filters_by_prefix() {
    let mut s = Session::new();
    for name in ["b", "a_", "Z", "a-", "a0", "_x", "a.fifo", "ab"] {
        let fifo = name.ends_with(".fifo");
        create(&mut s, name, json!({"Fifo": fifo}));
    }
    assert_eq!(
        names(&mut s, json!({"Command": "ListQueues"})),
        json!(["Z", "_x", "a-", "a.fifo", "a0", "a_", "ab", "b"])
    );
    assert_eq!(
        names(&mut s, json!({"Command": "ListQueues", "Prefix": "a"})),
        json!(["a-", "a.fifo", "a0", "a_", "ab"])
    );
    assert_eq!(names(&mut s, json!({"Command": "ListQueues", "Prefix": ""})).as_array().unwrap().len(), 8);
    assert_eq!(names(&mut s, json!({"Command": "ListQueues", "Prefix": null})).as_array().unwrap().len(), 8);
    assert_eq!(names(&mut s, json!({"Command": "ListQueues", "Prefix": "zz"})), json!([]));
    s.err(json!({"Command": "ListQueues", "Prefix": 1}), "InvalidParameterValue");
}

#[test]
fn deleting_a_queue_unsets_dead_letter_configuration_pointing_at_it() {
    let mut s = Session::new();
    create(&mut s, "d", json!({}));
    create(&mut s, "q", json!({"DeadLetterQueue": "d", "MaxReceiveCount": 2}));
    s.ok(json!({"Command": "DeleteQueue", "QueueName": "d"}));
    let a = attributes(&mut s, "q");
    assert_eq!(a.get("DeadLetterQueue"), None);
    assert_eq!(a.get("MaxReceiveCount"), None);
    s.err(json!({"Command": "DeleteQueue", "QueueName": "d"}), "QueueDoesNotExist");
    create(&mut s, "d", json!({}));
    assert_eq!(attributes(&mut s, "q").get("DeadLetterQueue"), None);
}

#[test]
fn queue_lookup_is_exact_for_every_command() {
    let mut s = Session::new();
    create(&mut s, "q", json!({}));
    for name in ["Q", "q ", "", "q.fifo", "no such"] {
        for command in ["GetQueueAttributes", "DeleteQueue", "PurgeQueue"] {
            s.err(json!({"Command": command, "QueueName": name}), "QueueDoesNotExist");
        }
    }
    for command in ["GetQueueAttributes", "DeleteQueue", "PurgeQueue"] {
        s.err(json!({"Command": command}), "MissingParameter");
        s.err(json!({"Command": command, "QueueName": 1}), "InvalidParameterValue");
    }
}
