    let moved = receive(&mut s, "d.fifo", 10);
    assert_eq!((moved[0]["Body"].clone(), moved[0]["GroupId"].clone(), moved[0]["SequenceNumber"].clone()), (json!("first"), json!("g"), json!(2)));
